import type { Result } from './result.ts';
// `data` exists only on the ok branch. Narrow on `r.ok` first.
export function dataOr<T>(r: Result<T>, fallback: T): T {
  return r.data;
}

export type Result<T> =
  | { ok: true; data: T }
  | { ok: false; error: string };
export function ok<T>(data: T): Result<T> { return { ok: true, data }; }
export function err<T>(error: string): Result<T> { return { ok: false, error }; }

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dataOr } from '../src/app.ts';
import { ok, err } from '../src/result.ts';
test('reads data on success', () => { assert.equal(dataOr(ok(7), 0), 7); });
test('falls back on error', () => { assert.equal(dataOr(err<number>('nope'), 0), 0); });

