import type { Booking } from './booking.ts';
// `minutes` is readonly. Return a new Booking instead of mutating it.
export function extend(b: Booking, add: number): Booking {
  b.minutes = b.minutes + add;
  return b;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { extend } from '../src/app.ts';
import { sample } from '../src/booking.ts';
test('extend returns a new booking with more minutes', () => {
  const longer = extend(sample, 30);
  assert.equal(longer.minutes, 90);
  assert.equal(sample.minutes, 60);
});

